import re
import os

RLM_SESSION_DIR = os.environ.get('RLM_SESSION_DIR')
if RLM_SESSION_DIR:
    session_file = os.path.join(RLM_SESSION_DIR, '../../sessions', os.path.basename(RLM_SESSION_DIR) + '.jsonl')
    print(f"Looking for: {session_file}")
    if os.path.exists(session_file):
        with open(session_file) as f:
            content = f.read()
        # Find demo pairs
        for m in re.finditer(r'Demo pair (\d+)', content):
            at = m.start()
            # Try to find the next "Test input" or action
            next_match = re.search(r'(Test input|Wrong attempts)', content[at+1:at+1000])
            if next_match:
                end = m.end() + next_match.start()
                chunk = content[m.end():end-1].strip()
                print(f"Dem after '{m.group(1)}':")
                print(chr(10).join(chunk[:100]))
    else:
        print("Could not find session file")
else:
    print("RLM_SESSION_DIR not set")

